public class OrdersServlet extends HttpServlet {          // container owns the lifecycle
    @Override public void init(ServletConfig cfg) { pool = openPool(cfg); }
    @Override protected void doGet(HttpServletRequest req, HttpServletResponse res)
            throws IOException {
        res.getWriter().write(renderOrders(pool));          // called by the container
    }
    @Override public void destroy() { pool.close(); }
}

